    public static function key(string $source):string{return'mailing_'.substr(hash('sha256',$source),0,24);}
    public static function messages(string $locale):array{$english=explode('-',$locale,2)[0]==='en';$out=[];foreach(self::ENGLISH as$source=>$value)$out[self::key($source)]=$english?$value:$source;return$out;}
    public static function text(string $source,array $messages,array $values=[]):string
    {
        if(str_starts_with($source,'Serienfeld fehlt oder ist leer: ')){$values=['field'=>substr($source,strlen('Serienfeld fehlt oder ist leer: '))];$source='Serienfeld fehlt oder ist leer: {field}';}
        elseif(str_starts_with($source,'Postanschrift fehlt bei ')&&str_ends_with($source,'. Empfängerauswahl korrigieren.')){$values=['name'=>substr($source,strlen('Postanschrift fehlt bei '),-strlen('. Empfängerauswahl korrigieren.'))];$source='Postanschrift fehlt bei {name}. Empfängerauswahl korrigieren.';}
        $text=$messages[self::key($source)]??$source;
        return preg_replace_callback('/\{([a-z_]+)\}/',static fn(array $match):string=>array_key_exists($match[1],$values)?(string)$values[$match[1]]:$match[0],$text);
    }
    public static function browser(array $messages):array{$out=[];foreach(self::BROWSER as$source)$out[$source]=self::text($source,$messages);return$out;}
